use serde::{Deserialize, Deserializer, Serialize, Serializer};

/// Operations on a presence-aware model field generated by [`crate::model`].
pub trait FieldState {
    type Value;
    fn is_missing(&self) -> bool;
    fn is_null(&self) -> bool;
    fn value(&self) -> Option<&Self::Value>;
    fn into_value(self) -> Option<Self::Value>;
    fn is_present(&self) -> bool {
        !self.is_missing()
    }
}

/// Macro support type. Declare business fields with `#[json(presence)]`.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub enum Field<T, const LENIENT: bool = false> {
    #[default]
    Missing,
    Null,
    Value(T),
    /// Only lenient fields can contain a rejected, but syntactically valid value.
    Invalid,
}

impl<T, const LENIENT: bool> Field<T, LENIENT> {
    pub fn missing() -> Self {
        Self::Missing
    }
    pub fn is_missing(&self) -> bool {
        matches!(self, Self::Missing)
    }
    pub fn set(&mut self, value: T) {
        *self = Self::Value(value);
    }
    pub fn set_null(&mut self) {
        *self = Self::Null;
    }
    pub fn unset(&mut self) {
        *self = Self::Missing;
    }
}

impl<T, const LENIENT: bool> From<T> for Field<T, LENIENT> {
    fn from(value: T) -> Self {
        Self::Value(value)
    }
}

impl<T, const LENIENT: bool> FieldState for Field<T, LENIENT> {
    type Value = T;
    fn is_missing(&self) -> bool {
        self.is_missing()
    }
    fn is_null(&self) -> bool {
        matches!(self, Self::Null)
    }
    fn value(&self) -> Option<&T> {
        match self {
            Self::Value(value) => Some(value),
            _ => None,
        }
    }
    fn into_value(self) -> Option<T> {
        match self {
            Self::Value(value) => Some(value),
            _ => None,
        }
    }
}

impl<'de, T: Deserialize<'de>, const LENIENT: bool> Deserialize<'de> for Field<T, LENIENT> {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        if LENIENT {
            #[derive(Deserialize)]
            #[serde(untagged)]
            enum Input<T> {
                Typed(T),
                Other(serde::de::IgnoredAny),
            }
            Ok(match Option::<Input<T>>::deserialize(deserializer)? {
                None => Self::Null,
                Some(Input::Typed(value)) => Self::Value(value),
                Some(Input::Other(_)) => Self::Invalid,
            })
        } else {
            Ok(match Option::<T>::deserialize(deserializer)? {
                Some(value) => Self::Value(value),
                None => Self::Null,
            })
        }
    }
}

impl<T: Serialize, const LENIENT: bool> Serialize for Field<T, LENIENT> {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::Value(value) => value.serialize(serializer),
            Self::Null | Self::Invalid => serializer.serialize_none(),
            Self::Missing => Err(serde::ser::Error::custom(
                "missing field must be omitted by its model",
            )),
        }
    }
}
